#!/usr/bin/env bash
# FluxPlayer overlay: brings in the Next Player base and applies the FluxPlayer changes.
# Run from the root of the fluxplayer repository.
set -euo pipefail

echo "== fetching Next Player base =="
rm -rf /tmp/base
git clone --depth 1 https://github.com/anilbeesetti/nextplayer.git /tmp/base
tar -C /tmp/base --exclude=.git -cf - . | tar -xf -
rm -rf /tmp/base

echo "== unpacking FluxPlayer overlay =="
printf '%s' '' | base64 -d | tar -xzf - -C /tmp
python3 /tmp/apply.py

echo "== overlay done =="
